import{_ as a,o,c as t,a4 as n}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0039 — Journalisation applicative : une ligne JSON par événement, sur la sortie standard","description":"Extrait de docs/adr/0039-journalisation-applicative.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0039 — Journalisation applicative : une ligne JSON par événement, sur la sortie standard","description":"Extrait de docs/adr/0039-journalisation-applicative.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0039-journalisation-applicative.md","filePath":"developpeurs/adr/0039-journalisation-applicative.md"}'),r={name:"developpeurs/adr/0039-journalisation-applicative.md"};function i(s,e,u,d,c,l){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0039--journalisation-applicative--une-ligne-json-par-événement-sur-la-sortie-standard" tabindex="-1">ADR-0039 — Journalisation applicative : une ligne JSON par événement, sur la sortie standard <a class="header-anchor" href="#adr-0039--journalisation-applicative--une-ligne-json-par-événement-sur-la-sortie-standard" aria-label="Permalink to &quot;ADR-0039 — Journalisation applicative : une ligne JSON par événement, sur la sortie standard {#adr-0039--journalisation-applicative--une-ligne-json-par-événement-sur-la-sortie-standard}&quot;">​</a></h1><p><strong>Date :</strong> 23 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit du 10 septembre 2026, constat P1 n°6 (« Aucune journalisation applicative ») ; s&#39;appuie sur l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0027-adaptateurs-d-exploitation-livres-inactifs">ADR-0027</a>, l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0031-limitation-de-debit">ADR-0031</a> et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0038-pieces-jointes-des-formulaires-publics">ADR-0038</a> ; complète l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0035-plan-de-site-flux-et-robots">ADR-0035</a> (<code>X-Robots-Tag</code>, <code>NoIndexMiddleware</code>)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Un seul module de l&#39;API journalisait quoi que ce soit : <code>app/core/rate_limit.py</code>, sur son propre logger <code>teuthis.rate_limit</code>, qui composait lui-même une chaîne JSON avec <code>json.dumps</code>. Aucune configuration de <code>logging</code> n&#39;existait ailleurs — aucun niveau réglé, aucun format déclaré, aucun gestionnaire branché. Une erreur 500 en production ne laissait donc aucune trace exploitable : ni la route en cause, ni la pile d&#39;appel, ni de quoi corréler le signalement d&#39;un usager à ce qui s&#39;était réellement passé côté serveur. Les pannes des adaptateurs livrés inactifs (ADR-0027) — captcha, courriel, antivirus, disjoncteur IA — n&#39;étaient elles aussi visibles qu&#39;à l&#39;effet qu&#39;elles produisaient (un 503, un envoi resté <code>pending</code>), jamais journalisées.</p><p>La question n&#39;était pas seulement technique : un journal applicatif est aussi une surface RGPD. Une ligne « pratique » qui recopierait une adresse IP, un identifiant de compte ou une chaîne de requête porteuse d&#39;un jeton (export ZIP par jeton, ADR-0032 ; suivi de dossier par référence) créerait une seconde base de données personnelles, sans durée de conservation déclarée au registre des traitements — exactement l&#39;écueil que l&#39;ADR-0030 avait déjà fermé pour <code>notification_deliveries.context</code>.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Le Core journalise en JSON structuré sur la sortie standard, avec la même discipline « rien de personnel, rien de secret » que <code>app/core/rate_limit.py</code> applique déjà.</strong></p><h3 id="1-un-seul-format-un-seul-socle" tabindex="-1">1. Un seul format, un seul socle <a class="header-anchor" href="#1-un-seul-format-un-seul-socle" aria-label="Permalink to &quot;1. Un seul format, un seul socle {#1-un-seul-format-un-seul-socle}&quot;">​</a></h3><p><code>app/core/logging.py</code> définit <code>configure_logging(level)</code> : un unique gestionnaire (<code>StreamHandler</code> sur <code>stdout</code>, formateur JSON) branché sur le logger <code>teuthis</code>, parent de tous les loggers du Core (<code>teuthis.rate_limit</code>, <code>teuthis.requetes</code>, <code>teuthis.captcha</code>, <code>teuthis.notifications</code>, <code>teuthis.ia</code>, <code>teuthis.composition</code>…). <code>propagate</code> y est coupé, pour qu&#39;une ligne ne remonte pas une seconde fois, non structurée, au logger racine de Python.</p><p>Chaque ligne porte, en français : <code>horodatage</code> (ISO 8601 UTC), <code>niveau</code>, <code>journal</code> (nom du logger), <code>evenement</code> (le message, un identifiant court en snake_case — <code>requete</code>, <code>erreur_non_geree</code>, <code>demarrage</code>, <code>limite_de_debit</code>…), les champs de <code>extra={&quot;champs&quot;: {...}}</code> fusionnés au premier niveau, et <code>requete_id</code> s&#39;il y a une requête HTTP en cours. <code>trace</code> (texte du traceback) n&#39;apparaît que si <code>exc_info</code> est fourni. Sérialisation <code>ensure_ascii=False</code>, <code>default=str</code>.</p><p><strong>Idempotent.</strong> <code>app/main.py</code> et <code>app/cli/scheduler.py</code> l&#39;appellent tous deux au démarrage — ce sont deux processus qui composent la même application (<code>app/composition.py</code>) — et un second appel ajuste le gestionnaire déjà posé plutôt que d&#39;en empiler un second, qui aurait doublé chaque ligne.</p><h3 id="2-log_level-vérifié-comme-les-autres-réglages-de-production" tabindex="-1">2. <code>LOG_LEVEL</code>, vérifié comme les autres réglages de production <a class="header-anchor" href="#2-log_level-vérifié-comme-les-autres-réglages-de-production" aria-label="Permalink to &quot;2. `LOG_LEVEL`, vérifié comme les autres réglages de production {#2-log_level-vérifié-comme-les-autres-réglages-de-production}&quot;">​</a></h3><p><code>app/core/config.py</code> porte <code>log_level: str = &quot;INFO&quot;</code>. <code>DEBUG</code>, <code>INFO</code>, <code>WARNING</code> ou <code>ERROR</code>, insensible à la casse. Vérifié à l&#39;import de <code>app/core/logging.py</code> (<code>validate_log_level</code>), même patron que <code>rate_limit_*</code> (<code>app/core/rate_limit.py</code>) et <code>ANTIVIRUS_CLAMD_URL</code> (<code>app/antivirus/__init__.py</code>) : une valeur qui n&#39;est aucun des quatre niveaux empêche l&#39;API et l&#39;ordonnanceur de démarrer, plutôt que de tomber en silence sur un niveau par défaut.</p><h3 id="3-une-ligne-par-requête-sans-rien-quelle-ne-devrait-porter" tabindex="-1">3. Une ligne par requête, sans rien qu&#39;elle ne devrait porter <a class="header-anchor" href="#3-une-ligne-par-requête-sans-rien-quelle-ne-devrait-porter" aria-label="Permalink to &quot;3. Une ligne par requête, sans rien qu&#39;elle ne devrait porter {#3-une-ligne-par-requête-sans-rien-quelle-ne-devrait-porter}&quot;">​</a></h3><p><code>app/core/request_log.py</code> monte <code>RequestLogMiddleware</code>, un intergiciel ASGI brut — comme <code>NoIndexMiddleware</code> — pour ne jamais tamponner une réponse en flux (téléchargement, export RGPD).</p><p>Une ligne par requête HTTP, niveau INFO (<code>evenement: &quot;requete&quot;</code>) sous 500, ERROR à partir de 500 : <code>methode</code>, <code>route</code> (le <strong>gabarit</strong> de la route, <code>request.scope[&quot;route&quot;].path</code>, ou la chaîne littérale <code>&quot;(aucune route)&quot;</code> faute de route appariée), <code>statut</code>, <code>duree_ms</code>, <code>requete_id</code>. <code>/health</code> et <code>/ready</code> n&#39;en produisent aucune — des sondes à haute fréquence, sans intérêt d&#39;exploitation ligne à ligne.</p><p><strong>N&#39;y figurent jamais :</strong> la chaîne de requête (elle porte des jetons), le chemin brut (le gabarit suffit et ne varie pas avec l&#39;identifiant demandé), le corps, les en-têtes, les cookies, l&#39;adresse IP, le user-agent, un identifiant de compte. Même règle que <code>app/core/rate_limit.py</code> applique déjà à ses propres lignes.</p><p><strong>Identifiant de requête.</strong> Repris de l&#39;en-tête entrant <code>X-Request-ID</code> seulement s&#39;il a la forme attendue (<code>^[A-Za-z0-9-]{8,64}$</code>) — une valeur reçue sans contrôle n&#39;irait pas telle quelle dans une ligne de journal ni dans une réponse — sinon un <code>uuid4().hex</code> est émis. Toujours rendu dans l&#39;en-tête de réponse, et posé dans une variable de contexte le temps de la requête : toute ligne émise pendant son traitement, même depuis <code>app/core/rate_limit.py</code> ou un adaptateur en panne, porte alors <code>requete_id</code> sans avoir à le répéter à chaque appel.</p><p><strong>Exception non gérée.</strong> Une ligne ERROR <code>evenement: &quot;erreur_non_geree&quot;</code>, avec la trace, part au journal ; l&#39;appelant reçoit un 500 JSON minimal, <code>{&quot;detail&quot;: &quot;erreur interne&quot;, &quot;requete_id&quot;: &quot;...&quot;}</code> — l&#39;identifiant que l&#39;agent de support relaie, et que l&#39;exploitant retrouve dans le journal. Les <code>HTTPException</code> ordinaires ne passent jamais par ce chemin : elles sont déjà résolues en réponse par Starlette avant d&#39;atteindre ce middleware ; seule une exception réellement non gérée y remonte. Ajouté <strong>avant</strong> <code>NoIndexMiddleware</code> dans <code>app/main.py</code> — donc à l&#39;intérieur de lui, Starlette empilant chaque middleware ajouté autour des précédents — pour que cette réponse 500, exception non gérée comprise, reçoive encore <code>X-Robots-Tag</code> en sortie.</p><p><strong>Exception au milieu d&#39;une réponse en flux.</strong> Si l&#39;en-tête de réponse est déjà parti (téléchargement, export), il n&#39;est plus possible d&#39;envoyer un 500 : la ligne <code>erreur_non_geree</code> est écrite avec le statut effectivement annoncé, puis l&#39;exception est relancée pour que le serveur coupe la connexion. L&#39;appelant voit un transfert interrompu plutôt qu&#39;un fichier tronqué présenté comme complet.</p><h3 id="4-le-journal-daccès-duvicorn-ne-le-remplace-pas--il-est-coupé" tabindex="-1">4. Le journal d&#39;accès d&#39;uvicorn ne le remplace pas : il est coupé <a class="header-anchor" href="#4-le-journal-daccès-duvicorn-ne-le-remplace-pas--il-est-coupé" aria-label="Permalink to &quot;4. Le journal d&#39;accès d&#39;uvicorn ne le remplace pas : il est coupé {#4-le-journal-daccès-duvicorn-ne-le-remplace-pas--il-est-coupé}&quot;">​</a></h3><p>Le journal d&#39;accès natif d&#39;uvicorn écrit l&#39;adresse du client et l&#39;URL complète, chaîne de requête comprise — exactement ce que la décision n°3 interdit. <code>--no-access-log</code> est ajouté à la commande uvicorn de <code>docker-compose.yml</code> (service <code>cms-api</code>) et au <code>CMD</code> du <code>Dockerfile</code> ; <code>access_log=False</code> est posé sur <code>uvicorn.run(...)</code> dans <code>app/cli/manage.py</code> (<code>runserver</code> d&#39;un projet scaffoldé, ADR-0023). La ligne <code>requete</code> du point 3 le remplace.</p><h3 id="5-appcorerate_limitpy-rejoint-le-contrat-commun" tabindex="-1">5. <code>app/core/rate_limit.py</code> rejoint le contrat commun <a class="header-anchor" href="#5-appcorerate_limitpy-rejoint-le-contrat-commun" aria-label="Permalink to &quot;5. `app/core/rate_limit.py` rejoint le contrat commun {#5-appcorerate_limitpy-rejoint-le-contrat-commun}&quot;">​</a></h3><p><code>logger.warning(&quot;limite_de_debit&quot;, extra={&quot;champs&quot;: {...}})</code> plutôt qu&#39;un <code>json.dumps</code> fait main — les mêmes champs qu&#39;avant (<code>politique</code>, <code>empreinte</code>, <code>compteur</code>, <code>seuil</code>, <code>fenetre_s</code>, <code>reessayer_dans_s</code>), seulement portés autrement. Rien n&#39;est affaibli : aucune adresse ni identifiant en clair n&#39;apparaissait déjà, et ça reste vrai.</p><h3 id="6-une-ligne-de-démarrage--quels-adaptateurs-sont-actifs" tabindex="-1">6. Une ligne de démarrage : quels adaptateurs sont actifs <a class="header-anchor" href="#6-une-ligne-de-démarrage--quels-adaptateurs-sont-actifs" aria-label="Permalink to &quot;6. Une ligne de démarrage : quels adaptateurs sont actifs {#6-une-ligne-de-démarrage--quels-adaptateurs-sont-actifs}&quot;">​</a></h3><p><code>app/composition.py</code> (<code>compose()</code>) journalise une ligne INFO <code>evenement: &quot;demarrage&quot;</code> : fournisseur de captcha actif (nom, ou <code>null</code> si aucun), repli captcha configuré, canal courriel actif (booléen), antivirus actif (booléen), mode de souveraineté IA, nombre d&#39;échangeurs OIDC branchés. Jamais un secret, jamais un hôte — un exploitant qui veut vérifier ce qui a démarré n&#39;a qu&#39;à lire cette ligne, plutôt que de relire quatre variables d&#39;environnement et de refaire le calcul.</p><p><code>compose()</code> peut être appelée plusieurs fois dans un même processus de test : une ligne de démarrage par appel est acceptable, ce n&#39;est pas un événement de haute fréquence.</p><h3 id="7-les-pannes-dadaptateur-journalisées-à-lendroit-où-elles-se-produisent" tabindex="-1">7. Les pannes d&#39;adaptateur, journalisées à l&#39;endroit où elles se produisent <a class="header-anchor" href="#7-les-pannes-dadaptateur-journalisées-à-lendroit-où-elles-se-produisent" aria-label="Permalink to &quot;7. Les pannes d&#39;adaptateur, journalisées à l&#39;endroit où elles se produisent {#7-les-pannes-dadaptateur-journalisées-à-lendroit-où-elles-se-produisent}&quot;">​</a></h3><p>Quatre familles, chacune avec un <code>evenement</code> explicite, WARNING, et uniquement des champs techniques :</p><ul><li><code>captcha_injoignable</code> (<code>app/forms/captcha.py:assert_human</code>) : fournisseur configuré, exception rencontrée — jamais le jeton présenté ni l&#39;adresse de l&#39;appelant.</li><li><code>notification_non_partie</code> (<code>app/notifications/engine.py</code>, à l&#39;envoi et au ré-essai, quel que soit le canal — courriel ou autre) : canal, exception — jamais le destinataire ni le contenu du message.</li><li><code>antivirus_injoignable</code> (<code>app/api/public_forms.py</code>, dépôt de pièce jointe) : fournisseur, exception — jamais le nom du fichier déposé.</li><li><code>ia_disjoncteur_ouvert</code> (<code>app/ai/manager.py</code>, quand <code>CircuitBreaker.record_failure</code> fait basculer le circuit) : modèle, nature de l&#39;échec — une ligne à l&#39;<strong>ouverture</strong>, pas une par échec, sans quoi le journal grossirait au rythme des appels au fournisseur en panne.</li></ul><p>Ce sont les quatre familles où un service configuré mais injoignable est déjà traduit en 503 (ou en <code>pending</code>, pour le courriel) par le patron de l&#39;ADR-0027 ; aucune autre n&#39;est ajoutée par cette ADR.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Format texte libre</strong> (<code>logging.basicConfig</code> par défaut)</td><td>Illisible par un collecteur de journaux (Loki, ELK, CloudWatch) sans une expression régulière fragile pour chaque forme de ligne.</td></tr><tr><td><strong>Journal vers un fichier</strong></td><td>Un fichier dans le conteneur ne survit pas à son remplacement, et rotation/conservation redeviennent un problème applicatif alors que le superviseur les résout déjà pour <code>stdout</code>.</td></tr><tr><td><strong>Un middleware <code>BaseHTTPMiddleware</code></strong> pour la ligne par requête</td><td>Tamponne la réponse pour la relire : casserait un téléchargement en flux ou un export RGPD volumineux, exactement ce que <code>NoIndexMiddleware</code> évite déjà en ASGI pur.</td></tr><tr><td><strong>Journaliser le chemin brut plutôt que le gabarit</strong></td><td>Un identifiant de dossier ou de contenu dans chaque ligne de journal, sans durée de conservation déclarée : la même dérive que <code>notification_deliveries.context</code> avant l&#39;ADR-0030.</td></tr><tr><td><strong>Laisser le journal d&#39;accès d&#39;uvicorn actif, en plus</strong></td><td>Doublon de la ligne <code>requete</code>, avec l&#39;adresse IP et l&#39;URL complète en plus — l&#39;inverse de la décision n°3.</td></tr><tr><td><strong>Une ligne de panne à chaque appel en échec du disjoncteur IA</strong></td><td>Le journal grossirait au même rythme que les appels au fournisseur en panne, sans rien apprendre de plus après la première ligne.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Une exception non gérée laisse enfin une trace exploitable, corrélée à la réponse reçue par l&#39;appelant via <code>requete_id</code>.</li><li>Un exploitant peut vérifier ce qui a démarré (ligne <code>demarrage</code>) et surveiller les pannes des quatre familles d&#39;adaptateurs livrés inactifs sans rien de plus qu&#39;un lecteur de journal JSON.</li><li>Le journal d&#39;accès d&#39;uvicorn, seule source qui écrivait déjà l&#39;adresse IP et l&#39;URL complète dans ce dépôt, est coupé.</li></ul><p><strong>Négatives, et il y en a</strong></p><ul><li><strong>Encore un module transverse de plus à connaître</strong> avant de journaliser correctement dans un nouveau paquet — <code>extra={&quot;champs&quot;: {...}}</code>, jamais un message qui embarque les valeurs lui-même.</li><li><strong>Le format JSON est moins lisible à l&#39;œil nu</strong> qu&#39;une ligne texte, en développement comme dans un terminal ouvert sur les journaux d&#39;un conteneur ; c&#39;est le compromis assumé au profit d&#39;un collecteur de journaux.</li><li><strong>Aucun envoi vers un agrégateur externe n&#39;est fourni</strong> : ce module s&#39;arrête à <code>stdout</code>, comme le reste du Core s&#39;arrête à PostgreSQL pour ses propres compteurs (ADR-0031).</li><li><strong>La rotation et la conservation des journaux du conteneur restent à la charge de l&#39;exploitant</strong> — un journal technique n&#39;a pas de durée de conservation déclarée au registre des traitements, et ce n&#39;est pas au Core de l&#39;inventer.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Socle de journalisation, middleware de requête, ligne de démarrage, quatre familles de pannes d&#39;adaptateur journalisées, journal d&#39;accès d&#39;uvicorn coupé — <code>apps/api/app/core/logging.py</code>, <code>apps/api/app/core/request_log.py</code>, <code>apps/api/app/composition.py</code>, recette <code>apps/api/tests/test_journalisation.py</code>.</li><li>[ ] Brancher un envoi vers un agrégateur de journaux externe (Loki, ELK, CloudWatch…) : laissé à l&#39;exploitant, la sortie standard du conteneur est le seul contrat que le Core tient.</li><li>[ ] Rotation et conservation des journaux du conteneur : à la charge de l&#39;exploitant (superviseur, orchestrateur), comme pour tout journal technique sans durée de conservation déclarée au registre des traitements.</li></ul>',40)])])}const g=a(r,[["render",i]]);export{m as __pageData,g as default};
